INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'vampire', 'Vampire', 'Prédateur maudit : une Cour, un Sang noir, des voies communes.', '{"nature":"vampire","description":"Descendant de l’héritage Khinae corrompu par les Fléaux, le Vampire est un prédateur surnaturel vivant plutôt qu’un cadavre animé. Les Sang-purs existent mais restent rares ; la majorité des Vampires de 2035 sont des Transformés, parfois très jeunes malgré l’existence d’anciens ayant perdu des décennies ou des siècles en torpeur. Cour d’origine, Maison, Sang noir et fidélités sont des axes distincts, tandis que la mort véritable condamne l’âme vampirique au Néant.","etats":{"V":"Corps humain, aucun bonus. Rester Voilé trop longtemps fait vieillir (Petite immortalité).","SR":"+1 Vigueur, +1 Volonté. Sens prédateurs ; Fascination (1 PA).","R":"+2 Vigueur, +1 Volonté. Prédation (1 PA), Stase (2 PA), Effacement, Physiologie maudite."},"traits_gratuits":[{"name":"Âme condamnée","access":"—","effect":"À la mort véritable, l’âme vampirique ne rejoint pas le Cycle : elle finit dans le Néant."},{"name":"Petite immortalité","access":"R","effect":"Le véritable corps ne vieillit pas tant que sa Nature est régulièrement Révélée."},{"name":"Physiologie maudite","access":"R","effect":"+3 Constitution contre les maladies ordinaires ; peut ralentir ou interrompre ses fonctions vitales."},{"name":"Sens prédateurs","access":"SR","effect":"Vision claire dans l’obscurité naturelle et perception fine du sang frais."},{"name":"Prédation sanguine","access":"R · 1 PA","effect":"Prédation par Pugilat ; une réussite peut rendre des PV selon le DR et la vitalité réellement prélevée."},{"name":"Effacement prédateur","access":"R","effect":"Peut tenter de se dissimuler dans des ombres suffisantes."},{"name":"Fascination vampirique","access":"SR · 1 PA","effect":"Charisme + Diplomatie contre Volonté + Force Mentale pour imposer l’attention."},{"name":"Stase","access":"R · 2 PA","effect":"Le Vampire devient inerte ; la dégradation naturelle et les hémorragies s’interrompent."},{"name":"Malédiction vampirique","access":"R","effect":"La Révélation expose la corruption à ses contre-forces, notamment le Soleil Ennemi."}],"malediction":"Au soleil direct, 2 PV irréductibles par round. Âme condamnée : à la mort véritable, le Néant.","choix_creation":["cour","sang_noir"],"maitrise":"Un Sang est maîtrisé après 4 PTV investis dans sa voie (règle de la carte Vampire, décision 21) ; on peut alors éveiller un autre Sang pour 3 PTV.","cout_eveil":3,"faim":false,"droits_acquis":"Les talents achetés avant les voies restent acquis, même si leur combinaison ne respecte plus l''ordre des paliers ou des portes ; la règle vaut pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'vampire_cour', 'Cour d''origine', NULL, '{"nature":"vampire","gratuit":"Empreinte","choix":"unique_a_la_creation"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'vampire_sang_noir', 'Sang noir', NULL, '{"nature":"vampire","gratuit":null,"choix":"unique_a_la_creation","eveil":"3 PTV une fois un Sang maîtrisé"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'vampire_voies_communes', 'Voies communes', NULL, '{"nature":"vampire","gratuit":null,"choix":"cumulable"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_cour_krovni_rytsari', 'Krovni Rytsari', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","cour":"krovni_rytsari","description":"Grande tradition occidentale de la noblesse vampirique, la Krovni organise le pouvoir autour du rang, du serment, du commandement et de la guerre. Ses structures féodales se sont adaptées aux holdings, sociétés de sécurité, réseaux politiques ou criminels modernes : l’honneur y est réel, mais l’intrigue et la stratégie à très long terme le sont tout autant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'predateur_de_guerre', 'Prédateur de guerre', NULL, '{"nature":"vampire","cout":0,"palier":"empreinte","porte":null,"acces":"R","texte_court":null,"texte_reference":"Tant qu’il n’est pas Surpris, le Vampire gagne +3 à sa Défense passive et active contre les attaques physiques.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'presence_du_conquerant', 'Présence du Conquérant', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R — 1 PA","texte_court":"Le rang écrase : la cible est Tendue et ne peut pas attaquer le Krovni en premier ce round, sauf si elle est elle-même noble ou officier.","texte_reference":"Charisme + Autorité contre Volonté + Force Mentale. Une réussite impose une pression prédatrice qui rend la cibleTenduetant qu’elle affronte directement le Krovni. Un DR particulièrement élevé peut justifier Panique si la fiction s’y prête.","lore":"Le Krovni laisse affleurer la certitude froide de celui qui se considère déjà maître du terrain. Face à lui, la cible ressent moins un charme qu’une pression de prédation organisée, comme si toute résistance devait d’abord convaincre le Vampire qu’elle mérite d’exister.","statut_regle":"correction","changements":"Ressort propre du Krovni (Q6)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'maitre_de_guerre', 'Maître de guerre', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — 1/round","texte_court":null,"texte_reference":"Lorsqu’un allié pouvant entendre le Krovni agit conformément à une instruction immédiate et claire, il reçoit+2sur le prochain test directement lié à cette instruction.","lore":"La tradition Krovni transforme le commandement en réflexe partagé. Un ordre bref venant d’un chef reconnu clarifie immédiatement la priorité du combattant qui l’entend, comme si l’escouade entière avait répété ce mouvement bien avant la bataille.","statut_regle":"correction","changements":"Passe au palier II, avant Ordre impérieux."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'ordre_imperieux', 'Ordre impérieux', NULL, '{"nature":"vampire","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"R — 1 PA","texte_court":"Ordre martial : sur un ennemi Tendu ou un subordonné, un ordre de combat (reculer, lâcher, se jeter à terre).","texte_reference":"Ordre bref : « Recule », « À genoux », « Lâche ton arme », « Tais-toi ». En cas de réussite, la cible exécute l’ordre immédiatement ou perd1 PAen résistant à l’impulsion.","lore":"La voix du Krovni prend l’ascendant brutal d’un prédateur habitué à être obéi. L’injonction est courte, physique, presque impossible à ignorer sans perdre un instant à lutter contre l’impulsion qu’elle dépose dans le corps.","statut_regle":"correction","changements":"Coût 2 → 3 (palier III) ; ressort martial (Q6)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_cour_alghul_almalakiu', 'Alghul Almalakiu', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","cour":"alghul_almalakiu","description":"Issue des premières civilisations mésopotamiennes, l’Alghul considère l’ancienneté comme une accumulation irremplaçable de savoirs, de langues, de rites et de souvenirs. Sa culture de conservation s’étend aux morts, au sang, aux restes et désormais aux archives numériques : détruire un ancien peut équivaloir à brûler une bibliothèque unique."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'echo_des_morts', 'Écho des Morts', NULL, '{"nature":"vampire","cout":0,"palier":"empreinte","porte":null,"acces":"R","texte_court":null,"texte_reference":"En touchant un cadavre ou une quantité significative de sang, le Vampire perçoit des traces utiles laissées par la mort : cause probable, violence, émotion finale, présence marquante, etc.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_memoriel', 'Sang mémoriel', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR","texte_court":null,"texte_reference":"En goûtant le sang d’une créature : Esprit + Perception pour extraire une impression récente forte — peur, douleur, visage, lieu, sensation. Le DR augmente la précision.","lore":"Une gorgée de sang peut porter l’écho d’une émotion récente. Peur, douleur, lieu ou visage remontent sans ordre parfait, fragments sensoriels que l’Alghul doit assembler sans les confondre avec un souvenir complet de la victime.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'interroger_les_restes', 'Interroger les restes', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"L’Empreinte devient précise. Poser au MJ1 question + 1 par DRsur les dernières heures du défunt, dans la limite de ce que son corps ou son sang peut raisonnablement avoir « connu ».","lore":"Chez les Alghul, un cadavre n’est pas immédiatement muet. Sang, tissus et dernières tensions du corps conservent des impressions que le Vampire sait lire comme les pages déchirées d’un témoignage incapable de mentir mais aussi incapable d’expliquer ce qu’il n’a jamais perçu.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_preserve', 'Sang préservé', NULL, '{"nature":"vampire","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R — rituel","texte_court":null,"texte_reference":"Le Vampire sait préparer une quantité de son propre sang afin qu’elle puisse servir d’ancrage à un rituel Alghul de restauration s’il meurt. Le Talent ne ressuscite personne seul : il faut un corps compatible, des praticiens, du temps et les conditions de l’histoire.","lore":"L’Alghul traite son propre sang comme une archive biologique de lui-même. Préparé selon les rites de Cour, il peut devenir l’ancrage autour duquel d’autres tenteront un jour de reconstruire ce qui aurait normalement été perdu avec sa mort.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_cour_oru_ayeraye', 'Oru Ayeraye', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","cour":"oru_ayeraye","description":"L’Oru réunit l’héritage de plusieurs anciennes Cours africaines marquées par les guerres de lignées, les puissances d’ombre et les alliances avec des Deimons. La maîtrise des Ténèbres et la relation aux créatures liées aux Maisons y comptent souvent autant que le lignage lui-même, selon des rapports allant du partenariat à l’exploitation réciproque."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'enfant_des_tenebres', 'Enfant des Ténèbres', NULL, '{"nature":"vampire","cout":0,"palier":"empreinte","porte":null,"acces":"R · 1 PA","texte_court":null,"texte_reference":"Dans une zone suffisamment obscure, le Vampire fait un avec l’ombre. Tant que l’effet s’applique, il n’est pas vu et ne peut être directement ciblé ; ce n’est pas un Couvert matériel et aucun capteur profane ne le contourne.","statut_regle":"correction","changements":"L''effet cesse dès qu''il attaque ou agit contre quelqu''un (clôture du 29/10, Q3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'marche_dans_les_ombres', 'Marche dans les ombres', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Tant qu’il demeure dans une zone suffisamment sombre, le Vampire peut se déplacer sans quitter son état d’Enfant des Ténèbres. Il le perd s’il attaque, manifeste un pouvoir évident ou rejoint une zone suffisamment éclairée.","lore":"Le Vampire apprend à demeurer dans l’effacement tant que l’obscurité lui offre une continuité. Il glisse d’une zone sombre à l’autre sans rompre la discrétion surnaturelle, jusqu’au moment où violence ou lumière le force à redevenir pleinement présent.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'ombre_predatrice', 'Ombre prédatrice', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Lorsqu’il quitte l’état d’Enfant des Ténèbres pour attaquer une cible qui ne pouvait pas le percevoir, celle-ci est considérée comme Surprise contre cette attaque.","lore":"L’Oru transforme la sortie des ténèbres en instant de chasse. Lorsque l’ennemi ne savait même pas où regarder, la première attaque surgit avant que son instinct ait eu le temps de replacer le prédateur dans le monde visible.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'lien_du_deimon', 'Lien du Deimon', NULL, '{"nature":"vampire","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Permet d’établir un lien durable avec un Deimon compatible lié aux traditions de sa Maison. Le Talent ne fournit pas la créature : elle doit être rencontrée ou obtenue dans le récit. Le lien utilise le moteur transversal des Compagnons liés ; le Deimon reste un PNJ réel et ne possède aucun pool de PA indépendant.","lore":"Dans l’Oru, un Deimon lié n’est ni un objet ni une invocation jetable. Le pacte reconnaît une créature réelle, avec sa volonté et son histoire, puis tisse entre les deux partenaires une proximité assez profonde pour survivre aux scènes où ils sont séparés.","statut_regle":"correction","changements":"Coût 2 → 3 (palier III)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_cour_ihuito_meztzi', 'Ihuito Meztzi', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","cour":"ihuito_meztzi","description":"L’Ihuito a prospéré dans les Amériques sous l’ombre de Quetzalcoatl. Le sang y est à la fois nourriture, héritage, puissance et continuité sacrée ; la Cour assume frontalement la prédation et conserve une histoire où religion, autorité et condition vampirique se sont longtemps confondues."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'cycle_du_sang', 'Cycle du Sang', NULL, '{"nature":"vampire","cout":0,"palier":"empreinte","porte":null,"acces":"R","texte_court":null,"texte_reference":"Une fois par scène, après une Prédation sanguine réussie, le prochain Talent de Sang utilisé avant la fin du round coûte 1 PA de moins, minimum 0.","statut_regle":"correction","changements":"La réduction de 1 PA vaut pour le premier talent de Sang de chaque round jusqu''à la fin de la scène (clôture du 29/10, Q3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_exalte', 'Sang exalté', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Après s’être nourri, le Vampire peut renoncer à une partie de la récupération obtenue afin de recevoir+3 sur le prochain jet lié à un Talent de Sangdurant la scène.","lore":"Le sang fraîchement pris ne sert pas uniquement à réparer le corps. L’Ihuito peut retenir une part de cette vigueur et la faire circuler dans un pouvoir hématique précis, préférant l’exaltation immédiate à la récupération.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'offrande_sanglante', 'Offrande sanglante', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Lors de la préparation d’un Talent de Sang, le Vampire peut payer de sa propre vitalité :2 PV remplacent 1 PA, une seule fois par activation.","lore":"L’Ihuito ne sépare jamais complètement puissance et sacrifice. Lorsque le temps manque, le Vampire peut verser sa propre vitalité dans la préparation d’un pouvoir de Sang, payant avec sa chair ce qu’il n’a pas le loisir d’accomplir patiemment.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_du_dieu', 'Sang du Dieu', NULL, '{"nature":"vampire","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R — 1/scénario","texte_court":null,"texte_reference":"Après avoir bu une quantité significative de sang d’une créature surnaturelle, conserver jusqu’à la fin de la scène unepropriété physique simplede cette créature, choisie avec le MJ parmi celles réellement présentes dans sa nature. Talent rare et fortement encadré.","lore":"Après avoir bu une créature surnaturelle, l’Ihuito peut conserver brièvement l’une de ses évidences corporelles. Ce n’est ni une copie d’âme ni un vol de pouvoir complet : seulement une qualité physique que le sang a appris à reproduire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_cour_shi_hun_zhe', 'Shi Hun Zhe', NULL, '{"nature":"vampire","forme":"progression","verrou":"ordre_paliers","cour":"shi_hun_zhe","description":"Le Shi Hun Zhe rassemble d’anciennes lignées d’Extrême-Orient autour de l’œuvre de Xinya et d’une lecture du Vampire comme être fondamentalement déséquilibré entre Yin, Yang, Hun et Po. Sa culture a conservé une architecture administrative quasi impériale — ministères, justice, finances, diplomatie, sécurité — adaptée au monde de 2035."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'equilibre_derobe', 'Équilibre dérobé', NULL, '{"nature":"vampire","cout":0,"palier":"empreinte","porte":null,"acces":"R","texte_court":null,"texte_reference":"Après s’être nourri, une fois par scène, le Vampire peut consumer le Hun/Yang absorbé pour obtenir une résistance contre une faiblesse ou un effet surnaturel auquel sa Nature ne lui permettrait normalement pas de résister.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'souffle_du_yang', 'Souffle du Yang', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","texte_court":"Après une Prédation dans la scène, 1 PA, 1/scène : ignorer une faiblesse jusqu''à la fin du prochain round.","texte_reference":"Après s’être nourri, le Vampire peut consumer l’équilibre volé pourignorer jusqu’à la fin du roundles effets d’une faiblesse vampirique choisie.","lore":"Le sang fraîchement volé apporte assez de Yang pour soutenir momentanément ce que la condition vampirique rejette. Le Vampire consume cette réserve comme un souffle emprunté, protégeant brièvement son équilibre face à une faiblesse choisie.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'harmonie_impossible', 'Harmonie impossible', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — 1/scène","texte_court":"L''effet dure la scène ; dégâts de la faiblesse divisés par deux. Contre un effet automatique sans dégâts : Volonté + Force Mentale contre sa Puissance.","texte_reference":"Jusqu’à la fin de la scène, une faiblesse choisie est fortement réduite : les dégâts qu’elle inflige sont divisés par deux (arrondi au supérieur) et un effet normalement automatique autorise un test de résistance approprié.","lore":"Le Shi Hun Zhe atteint un équilibre que sa malédiction refuse normalement. Une faiblesse demeure présente mais cesse un temps d’être absolue, comme si Hun et Po avaient trouvé une position provisoire où aucun des deux ne laissait l’autre entraîner le Vampire vers sa chute.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'union_du_hun_et_du_po', 'Union du Hun et du Po', NULL, '{"nature":"vampire","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R — 1/scénario","texte_court":"1 PA, 1/scénario, après une Prédation dans la scène : annuler une malédiction pour la scène, y compris le Soleil.","texte_reference":"Le Vampire atteint momentanément un équilibre que sa Nature ne devrait pas permettre.Une malédiction vampirique choisie cesse complètement de s’appliquer jusqu’à la fin de la scène.Le soleil peut être choisi.","lore":"Pendant quelques instants, les deux principes que la malédiction maintient en conflit cessent de se déchirer. Le Vampire atteint une cohérence presque impossible où même l’une de ses grandes condamnations peut perdre entièrement prise sur lui.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_emprise', 'Emprise', NULL, '{"nature":"vampire","forme":"progression","verrou":"ordre_paliers","socle":"Fascination (carte de Nature)"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'charme_inhumain', 'Charme inhumain', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR","texte_court":"Une Fascination réussie rend aussi la cible confiante : +3 aux interactions sociales avec elle jusqu''à la fin de la scène, tant que ton comportement ne brise pas l''emprise.","texte_reference":"Après une Fascination réussie : +3 aux interactions sociales avec cette cible jusqu’à la fin de la scène, tant que le comportement du Vampire ne brise pas clairement l’emprise.","lore":"Après avoir déjà ouvert une brèche par la Fascination, le Vampire sait rester exactement dans l’angle où la cible veut encore l’écouter. Sa prédation sociale devient plus fluide tant qu’il ne commet rien qui oblige l’autre à reconnaître brutalement l’emprise.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'domination', 'Domination', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — 1 PA","texte_court":"En Révélé, une Fascination à DR 2+ peut aussi imposer un geste bref, exécuté avant la fin du prochain round de la cible. Elle paie normalement ses actions ; +3 pour résister à un ordre suicidaire ou contraire à une conviction fondamentale. Domination est intime : une cible, en tête-à-tête.","texte_reference":"Charisme + Autorité contre Volonté + Force Mentale. Imposer un ordre bref et immédiat. Une instruction manifestement suicidaire ou contraire à une conviction fondamentale donne le +3 circonstanciel normal pour résister.","lore":"La voix vampirique transforme un ordre simple en impulsion difficile à séparer de sa propre volonté. Les convictions profondes peuvent encore résister, mais quelques mots suffisent parfois à détourner le prochain geste avant que la cible comprenne qu’elle a été poussée.","statut_regle":"correction","changements":"Plus de jet séparé (Charisme + Autorité, 10 m) : se déclenche sur la Fascination à DR 2+."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'somnambulisme', 'Somnambulisme', NULL, '{"nature":"vampire","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"SR — 2 PA","texte_court":"L''emprise atteint le sommeil. Pour 2 PA, au contact d''une cible endormie, implanter une instruction simple et son déclencheur, valables le scénario.","texte_reference":"Sur une cible endormie ou inconsciente, implanter une suggestion simple ou provoquer un comportement somnambulique. Opposition mentale si la cible pourrait raisonnablement résister ; l’instruction peut attendre son déclenchement durant le scénario.","lore":"Dans un esprit endormi, la suggestion trouve moins de portes fermées. Le Vampire dépose une instruction simple parmi les rêves et laisse la cible l’accomplir plus tard comme une idée qui semblait déjà l’attendre au réveil.","statut_regle":"correction","changements":"Coût 2 → 3 (palier III)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_predateur', 'Prédateur', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","socle":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'faveur_de_la_nuit', 'Faveur de la nuit et Sens du chasseur', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R — passif","texte_court":"Chasseur nocturne : +3 Furtivité dans l''ombre et +3 Perception pour traquer une créature vivante ou blessée.","texte_reference":"+3 Furtivité dans les ombres ou l’obscurité. Effacement prédateur autorise certaines tentatives ; Faveur de la nuit rend le Vampire meilleur à ces tentatives.\n+3 Perception pour repérer, poursuivre ou retrouver une créature vivante ou blessée. Ne remplace pas les pouvoirs d’analyse du Sang Traqueur.","lore":"L’ombre accepte le Vampire avec une facilité prédatrice. Silhouette, mouvement et respiration se fondent mieux dans l’obscurité, non parce qu’il devient invisible mais parce que la nuit paraît naturellement cacher ce qui chasse en elle.","statut_regle":"correction","changements":"Fusion avec Sens du chasseur (Prédateur I)."}'::jsonb, 'published', ARRAY['sens_du_chasseur']::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'regeneration_de_sang', 'Régénération de sang et Insensibilité améliorée', NULL, '{"nature":"vampire","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"R — passif","texte_court":"Corps maudit : la Prédation rend 2 + DR PV au lieu de 1 + DR, et +3 Constitution contre poisons et drogues.","texte_reference":"Lors d’une Prédation sanguine, récupération de2 + DR PVau lieu de 1 + DR, toujours limitée par la vitalité réellement prélevée.\nLe +3 de Physiologie maudite s’applique aussi aux poisons et drogues ; le Vampire peut tenter de résister à certains effets ordinaires qui seraient normalement automatiques.","lore":"La prédation nourrit directement la réparation. Le sang arraché à la proie ne se contente pas d’apaiser la faim : il devient matière de reconstruction, refermant les blessures avec une efficacité proportionnelle à la vitalité réellement prise.","statut_regle":"correction","changements":"Fusion avec Insensibilité améliorée (Prédateur II)."}'::jsonb, 'published', ARRAY['insensibilite_amelioree']::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_stase', 'Stase', NULL, '{"nature":"vampire","forme":"progression","verrou":"ordre_paliers","socle":"Stase (carte de Nature)"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'stase_profonde', 'Stase profonde', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","texte_court":"En Stase, 2 PV par heure, et les blessures ne s''aggravent plus d''elles-mêmes.","texte_reference":"Récupération en Stase :2 PV/heure. Les blessures ordinaires ne peuvent pas spontanément dégrader davantage l’état du Vampire tant qu’il y demeure.","lore":"La Stase devient une véritable chambre de réparation plutôt qu’une simple immobilité. Le corps maudit se ferme aux dégradations ordinaires et travaille lentement à se reconstruire tant que rien ne vient le détruire de l’extérieur.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'dernier_sommeil', 'Dernier sommeil', NULL, '{"nature":"vampire","cout":3,"cout_actuel":3,"palier":"II","porte":null,"palier_double":null,"acces":"R — Réaction | 1/scénario — Prérequis : Stase profonde","texte_court":"Réaction, 1/scénario : une blessure qui franchirait le seuil de Mort laisse juste au-dessus et plonge en Stase.","texte_reference":"Lorsqu’une blessure devrait faire franchir le seuil de Mort, le Vampire sombre immédiatement en Stase et reste juste au-dessus de ce seuil. Ne protège pas d’un corps détruit ou d’un effet explicitement annihilant.","lore":"Lorsque la destruction approche trop près, la malédiction préfère parfois éteindre le Vampire plutôt que le laisser franchir le dernier seuil. Il s’effondre dans une Stase de survie, fragile refuge qui ne sauve rien si le corps lui-même cesse d’exister.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_ecarlate', 'Sang Écarlate — Anya', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"chasser par le sang","sang":"sang_ecarlate","portes":{"A":"Le sang","B":"La fureur"},"description":"Sang d’Anya centré sur la force, la vitesse et la perception hématique. Il transforme la lecture du sang en avantage de chasse puis permet au Vampire de pousser brutalement son corps au-delà de son régime ordinaire."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'vision_du_sang', 'Vision du Sang', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","texte_court":null,"texte_reference":"Perçoit le sang frais et la circulation des êtres vivants ; peut distinguer ces signatures malgré une faible obscuration ou un obstacle mince.","lore":"La circulation vivante devient visible derrière peau et faible obstacle. Pulsations, masses chaudes de sang et blessures fraîches composent une cartographie de la vie qui persiste même lorsque l’éclairage ordinaire ne suffit plus.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'traque_hematique', 'Traque hématique', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR","texte_court":null,"texte_reference":"Reconnaît un sang précis, le distingue des autres et peut suivre sa trace malgré une dissimulation ordinaire.","lore":"Un sang connu possède pour Anya une signature impossible à confondre avec une autre. Une goutte, une trace nettoyée trop vite ou une piste mêlée à d’autres reste identifiable comme le passage précis de la proie recherchée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'deferlement_ecarlate', 'Déferlement écarlate', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA","texte_court":"1 PA, 1/scène : +3 au prochain test physique effectué avant la fin du round.","texte_reference":"+3 au prochain test physique effectué avant la fin du round.","lore":"Le Sang d’Anya libère une poussée de puissance immédiatement utilisable par le corps. Muscles, coordination ou vitesse reçoivent ensemble cette brève montée hématique, comme si la circulation venait d’ouvrir toutes ses réserves au même instant.","statut_regle":"correction","changements":"1/scène au lieu de 1/round (décision 22, 31/10)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'surregime', 'Surrégime', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 1/scène","texte_court":null,"texte_reference":"Gagne immédiatement1 PA supplémentaire, même au-delà du maximum normal, à utiliser durant le round courant.","lore":"Le Vampire force son organisme à trouver encore un geste dans un round déjà saturé. Tout s’accélère — perception, décision, mouvement — au prix de faire fonctionner la prédation à un régime que le corps ordinaire ne pourrait soutenir.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_primal', 'Sang Primal — Lyssa', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"changer de corps","sang":"sang_primal","portes":{"A":"La bête","B":"La brume"},"description":"Sang de Lyssa consacré à la métamorphose animale et à la dissolution en brume. Il permet d’adopter des formes naturelles puis de traiter le corps vampirique comme une matière plus fluide, capable d’échapper aux contraintes physiques ordinaires."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'forme_animale', 'Forme animale', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R — 1 PA","texte_court":null,"texte_reference":"Prend la forme d’un animal naturel maîtrisé. Les aptitudes corporelles évidentes de cette forme deviennent utilisables ; l’équipement ordinaire ne s’adapte pas automatiquement.","lore":"Le Sang primal rappelle au corps une autre anatomie naturelle et la rend complète. Griffes, ailes, nage ou odorat suivent alors les capacités évidentes de l’animal choisi, tandis que vêtements et outils restent les problèmes d’un corps humain qu’il vient de quitter.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'menagerie', 'Ménagerie', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Maîtrise plusieurs formes animales et peut choisir celle adaptée à la scène.","lore":"Lyssa ne limite plus le Vampire à une seule réponse animale. Plusieurs morphologies sont mémorisées dans le Sang, chacune gardée comme une solution possible à ressortir lorsque terrain, fuite ou chasse réclament un autre corps.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corps_de_brume', 'Corps de brume', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — Réaction 1 PA","texte_court":"Se dissoudre : en plus du +3, finir son mouvement à 3 m, à travers une fente ou une grille.","texte_reference":"Se dissout brièvement en brume pour laisser traverser une agression physique ; les effets capables d’atteindre une forme immatérielle restent applicables.","lore":"La chair se défait juste assez longtemps pour qu’un coup ordinaire traverse une masse sans organes ni os. Le Vampire existe toujours dans cette vapeur, mais seules les attaques capables de toucher l’immatériel peuvent réellement le traiter comme avant.","statut_regle":"correction","changements":"Ressort propre du Vampire (Q6)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'brume_etouffante', 'Brume étouffante', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 2 PA, maintien","texte_court":null,"texte_reference":"Étend sa brume à une petite zone, gênant vision, respiration et déplacements selon la scène. Maintien normal : 1 PA/round.","lore":"Lyssa étend sa forme diffuse jusqu’à remplir l’espace. La brume s’accroche aux yeux, au souffle et aux trajectoires, donnant au Vampire une présence partout à la fois sans lui rendre pour autant un corps solide à cet endroit.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_hypocrite', 'Sang Hypocrite — Briaerus', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"tromper les sens","sang":"sang_hypocrite","portes":{"A":"Les doubles","B":"Les illusions"},"description":"Sang de Briaerus fondé sur le mensonge visuel, les doubles et l’illusion. Sa progression va de leurres locaux à des mises en scène multisensorielles capables de fausser toute une situation sans créer de matière réelle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'double_tenebreux', 'Double ténébreux', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR — 1 PA, maintien","texte_court":null,"texte_reference":"Crée un double crédible mais immatériel, capable de tromper la perception ordinaire.","lore":"Briaerus donne au Vampire un second corps qui ne possède ni poids ni chair. Assez crédible pour tromper les sens ordinaires, il emprunte apparence et mouvement sans jamais devenir une personne capable de saisir le monde.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'double_autonome', 'Double autonome', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Le double peut se déplacer indépendamment pour distraire, feinter ou attirer l’attention ; il n’inflige pas de dégâts par lui-même. Il ne possède aucun pool de PA : toute action tactiquement significative accomplie par le double utilise les PA du Vampire.","lore":"Le double de Briaerus cesse de suivre son créateur comme un reflet docile. Il peut attirer un regard, prendre un couloir ou feindre une intention ailleurs, illusion mobile dont chaque initiative reste néanmoins soutenue par l’attention réelle du Vampire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'fantasmagorie', 'Fantasmagorie', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR — 1 PA, maintien","texte_court":null,"texte_reference":"Crée une illusion locale simple. Une cible qui a une vraie raison de douter peut tenter une opposition appropriée.","lore":"Une scène simple peut être falsifiée par quelques détails bien choisis : silhouette, bruit, objet ou mouvement qui n’existe pas. L’illusion tient tant que rien ne pousse réellement l’observateur à demander au monde une preuve plus solide.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'grande_illusion', 'Grande illusion', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 2 PA, maintien","texte_court":null,"texte_reference":"Illusion multisensorielle couvrant une scène ou un environnement important.","lore":"Le Sang hypocrite ne se contente plus d’un leurre isolé. Sons, volumes, textures et ambiance peuvent composer un environnement mensonger assez vaste pour que plusieurs témoins partagent la même fausse scène.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_venimeux', 'Sang Venimeux — Huitzitia', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"empoisonner","sang":"sang_venimeux","portes":{"A":"Le venin","B":"La chaleur"},"description":"Sang d’Huitzitia mêlant perception thermique et production de toxines biologiques. Le Vampire apprend à façonner ses propres fluides en venins spécialisés puis à contaminer son environnement proche."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'venin_noir', 'Venin noir', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","texte_court":"Pour 1 PA, une dose dans tes fluides ; elle agit par morsure blessante, ingestion ou plaie ouverte. Vigueur + Constitution contre la Puissance ; en échec, −3 aux tests physiques pour la scène, sans cumul de doses.","texte_reference":"Le Vampire peut rendre ses fluides corporels toxiques. Après contact significatif, la cible résiste avec Constitution si l’effet est contestable.","lore":"Les fluides du Vampire deviennent eux-mêmes une arme biologique. Sang, salive ou sécrétion peuvent porter une toxicité que l’organisme adverse doit reconnaître et combattre après une exposition suffisamment réelle.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'venins_faconnes', 'Venins façonnés', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":"À la préparation, choisis un venin affaiblissant, un soporifique (endort après une minute hors combat) ou un paralysant (−3 aux tests moteurs et demi-Déplacement jusqu''à la fin du prochain round de la cible).","texte_reference":"À chaque sécrétion, choisir une orientation cohérente : paralysante, soporifique, douloureuse ou autre effet validé avec le MJ.","lore":"Le Sang venimeux apprend à choisir ce qu’il veut faire au corps plutôt qu’à produire une toxine unique. Sommeil, douleur ou paralysie deviennent des profils biologiques distincts, préparés selon l’effet recherché avant la sécrétion.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'effluves_toxiques', 'Effluves toxiques', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":"b","acces":"R — 2 PA, maintien","texte_court":"2 PA, maintien 1 PA/round : le venin choisi se diffuse dans un rayon de 3 m. Toute créature qui respire, alliés compris, résiste à l''entrée puis à sa prochaine activation si elle reste ; une réussite la protège pour le round.","texte_reference":"Diffuse ses toxines dans son environnement proche et crée une petite zone dangereuse.","lore":"Huitzitia ne garde plus son venin dans le corps. Une exhalaison, une brume ou des fluides dispersés rendent l’espace proche dangereux, transformant la proximité du Vampire en exposition plutôt que le seul contact direct.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'vision_thermique', 'Vision thermique', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","texte_court":"À 20 m, tu perçois les contrastes thermiques dans l''obscurité et les fumées non isolantes. Murs, vitres et écrans thermiques restent des obstacles.","texte_reference":"Perception infrarouge des sources de chaleur et des variations thermiques.","lore":"Huitzitia ajoute la chaleur au vocabulaire des formes visibles. Corps, moteurs et surfaces récemment touchées se détachent par leur température, révélant des présences que couleur et lumière ordinaire auraient pu dissimuler.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_masque', 'Sang Masqué — Kazuo', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"voler une identité","sang":"sang_masque","portes":{"A":"Le visage","B":"La voix"},"description":"Sang de Kazuo dédié à l’infiltration et à l’imitation. Presque entièrement utilisable en Semi-Révélation, il copie visage, voix et morphologie sans transmettre les souvenirs, compétences ou secrets de la personne imitée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'visage_vole', 'Visage volé', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR — 1 PA","texte_court":"1 PA : pour la scène, tu prends le visage d''une personne dont tu as bu le sang. Ni corps, ni voix, ni connaissances, ni capacités.","texte_reference":"Copie le visage d’une personne dont le Vampire s’est déjà nourri.","lore":"Le sang bu sert de mémoire morphologique. Les traits d’une ancienne proie remontent dans la chair du Vampire et remplacent son visage par une copie dont la crédibilité vient précisément de cette proximité hématique passée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mue_complete', 'Mue complète', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR","texte_court":"Avec le même PA, tu copies aussi le corps visible, à 25 % près de taille et de masse. Ni statistiques, ni équipement, ni aptitudes.","texte_reference":"Copie aussi la morphologie générale et les particularités physiques visibles.","lore":"Le masque gagne le reste du corps. Taille, proportions et particularités visibles peuvent rejoindre le visage déjà volé, produisant une imitation physique convaincante tant qu’aucun détail caché ou savoir personnel n’est exigé.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'voix_volee', 'Voix volée', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","texte_court":"Sans PA de plus pour parler, tu reproduis fidèlement la voix d''une personne dont tu as bu le sang. Une analyse acoustique ou une observation attentive garde son test de détection.","texte_reference":"Reproduit fidèlement la voix d’une personne dont il s’est nourri.","lore":"Une voix entendue de l’intérieur par le sang peut être reproduite bien au-delà d’une simple imitation. Timbre et cadence reviennent avec une fidélité surnaturelle, même lorsque le Vampire n’a jamais appris à parler comme cette personne.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mimetisme_parfait', 'Mimétisme parfait', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"SR","texte_court":"Ta voix copiée trompe d''office la reconnaissance vocale ordinaire et les proches de la personne. Une contradiction de connaissances ou de comportement peut toujours te trahir ; aucun souvenir ni secret acquis.","texte_reference":"Le Vampire reproduit surnaturellement la signature vocale complète de la cible : timbre, micro-intonations, rythme respiratoire, accent, cadence, hésitations, placement de voix et particularités acoustiques involontaires. Une personne connaissant intimement cette voix et une biométrie vocale ordinaire la reconnaissent normalement comme authentique. Le Talent ne fournit aucun souvenir, vocabulaire spécialisé, mot de passe ou connaissance personnelle de la cible.","lore":"Kazuo fait de la voix un masque jusque dans ses accidents minuscules. Souffle, hésitations, accent et micro-intonations deviennent assez fidèles pour tromper l’oreille intime comme la biométrie, sans offrir au Vampire les souvenirs qui expliqueraient quoi dire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_aveugle', 'Sang Aveugle — Ashream', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"percevoir sans voir","sang":"sang_aveugle","portes":{"A":"L''écho","B":"L''astral"},"description":"Sang d’Ashream tourné vers les perceptions non visuelles et le plan astral. Écholocation et vision astrale élargissent d’abord les sens, avant de permettre au Vampire de projeter sa conscience hors d’un corps laissé vulnérable."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'echolocation', 'Écholocation', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","texte_court":null,"texte_reference":"Perçoit précisément volumes, reliefs et mouvements par ultrasons, indépendamment de la lumière.","lore":"La lumière devient accessoire. Claquements, souffle ou ultrasons bâtissent dans l’esprit une géométrie de volumes et de mouvements où murs, corps et reliefs existent par la manière dont ils renvoient le son.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sonar_predateur', 'Sonar prédateur', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Étend la précision de l’écholocation et permet de percevoir certaines présences au travers d’obstacles minces.","lore":"L’écho cesse de décrire seulement la pièce immédiate. Le Vampire apprend à lire le retour des ultrasons avec une finesse prédatrice, distinguant mouvements et présences même lorsque de minces obstacles devraient les cacher à une vue ordinaire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'vision_astrale', 'Vision astrale', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","texte_court":null,"texte_reference":"Perçoit le plan astral et les présences qui s’y manifestent.","lore":"Le regard d’Ashream se décale vers ce qui n’appartient pas entièrement au monde matériel. Présences, silhouettes et phénomènes du plan astral prennent une forme lisible sans que le Vampire ait besoin d’abandonner son propre corps.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'projection_astrale', 'Projection astrale', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 2 PA, maintien","texte_court":null,"texte_reference":"Quitte son corps pour se déplacer astralement. Le corps reste totalement vulnérable ; sous pression, la projection suit les règles normales de maintien.","lore":"Ashream permet à la conscience de se détacher d’un corps devenu silencieux. Le Vampire traverse alors le plan astral comme une présence sans chair, sachant que son enveloppe laissée derrière lui demeure vulnérable à tout ce qui arrivera pendant son absence.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_traqueur', 'Sang Traqueur — Go’Ndai', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"disséquer la proie","sang":"sang_traqueur","portes":{"A":"L''anatomie","B":"Le sang animé"},"description":"Sang de Go’Ndai centré sur l’analyse anatomique et la manipulation hématique. Il lit le corps comme un réseau vivant, repère ses défaillances puis apprend à transformer le sang en outil, membre ou arme surnaturelle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'diagnostic_predateur', 'Diagnostic prédateur', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR — 1 PA","texte_court":null,"texte_reference":"Le Vampire lit directement l’organisme comme un réseau vivant : circulation, rythme cardiaque, oxygénation, tensions musculaires, hémorragies internes, fractures, lésions importantes, organes défaillants, intoxications physiologiquement actives et autres anomalies corporelles significatives, même sans signe extérieur. La lecture indique ce qui se passe dans le corps, pas nécessairement pourquoi : Soin, Science ou un savoir approprié restent nécessaires pour interpréter une pathologie inconnue, une modification extraterrestre ou une altération surnaturelle complexe. Ne révèle ni Nature, ni Sang, ni Talent, ni faiblesse surnaturelle abstraite.","lore":"Pour Go’Ndai, un organisme est un réseau lisible de flux, tensions et ruptures. Le Vampire voit hémorragie, fracture ou organe en difficulté sans confondre cette lecture physiologique avec la connaissance de la cause occulte ou extraterrestre qui l’a provoquée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'anatomie_fatale', 'Anatomie fatale', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Après avoir étudié une cible, la prochaine attaque réussie peut choisir une zone ou une Altération sans exiger le seuil de marge habituel ; les dégâts restent ceux de la marge réellement obtenue.","lore":"Go’Ndai transforme l’observation du corps en violence précise. Après avoir compris où la cible est vulnérable, le Vampire frappe directement l’articulation, l’organe ou la structure dont la défaillance changera réellement la suite du combat.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_anime', 'Sang animé', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA, maintien","texte_court":null,"texte_reference":"Anime son propre sang ou du sang répandu comme un membre supplémentaire capable de manipulations simples.","lore":"Le sang répandu se comporte comme un membre détaché mais encore obéissant. Il peut ramper, saisir ou déplacer de petites choses, prolongement rouge de la volonté du Vampire là où ses mains ne se trouvent pas.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'arme_hematique', 'Arme hématique', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","texte_court":"Le sang animé forme une lame, un fouet ou un projectile ; la forme choisie fixe la compétence d''attaque. Le projectile porte à 10 m au plus.","texte_reference":"Le sang animé peut former lame, fouet ou projectile surnaturel. La forme choisie détermine la compétence d’attaque appropriée ; les valeurs de DGT suivent l’équilibrage des armes de la campagne.","lore":"Le sang quitte sa fonction de fluide pour devenir outil de prédation. Lame, fouet ou projectile prennent forme à partir d’une matière qui reste liée au Vampire et se comporte comme une extension armée de sa circulation.","statut_regle":"correction","changements":"Portée du projectile réduite à 10 m (décision 22, 31/10)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_glacial', 'Sang Glacial — Vjärmod', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"contrôler","sang":"sang_glacial","portes":{"A":"Le toucher","B":"Le froid"},"description":"Sang de Vjärmod fondé sur le drain de chaleur et le gel surnaturel. Sa puissance commence au contact puis s’étend jusqu’à transformer une zone entière en environnement hostile par le froid."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'toucher_glacial', 'Toucher glacial', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","texte_court":"Une attaque de contact payée normalement inflige DGT 3 ; une blessure réelle impose −3 au prochain test physique de la cible avant la fin de son prochain round (1/round).","texte_reference":"Un contact volontaire peut engourdir ou paralyser par le froid ; Constitution résiste quand l’effet vise directement un adversaire.","lore":"Au contact, le Vampire aspire assez de chaleur pour faire hésiter nerfs et muscles. L’engourdissement peut devenir paralysie brève, sensation de chair étrangère laissée par une main plus froide que le milieu qui l’entoure.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'gel_brutal', 'Gel brutal', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R — 2 PA","texte_court":"2 PA, au contact, DGT 6 ; une blessure réelle divise le Déplacement par deux jusqu''à la fin du prochain round de la cible. Peut aussi geler un mécanisme exposé ou un petit objet.","texte_reference":"Gèle sévèrement un objet ou une partie du corps atteinte, avec conséquences fictionnelles adaptées.","lore":"Le froid se concentre assez vite pour figer matière ou chair avant qu’elles aient le temps de s’adapter. Ce qui est touché devient cassant, engourdi ou raide selon sa nature, marqué par une chute de température presque instantanée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'devorer_la_chaleur', 'Dévorer la chaleur', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — maintien","texte_court":"1 PA, maintien 1 PA/round : zone de froid de 3 m de rayon. À l''entrée, puis à chaque activation dans la zone, Vigueur + Constitution contre la Puissance ; en échec, −3 aux tests moteurs tant que la cible y reste.","texte_reference":"Absorbe progressivement la chaleur d’une petite zone et crée un danger environnemental.","lore":"Vjärmod ne produit pas d’abord du froid : il retire la chaleur. Autour du Vampire, l’énergie thermique disparaît progressivement, laissant air et surfaces tomber vers un silence glacé que le corps vivant reconnaît immédiatement comme dangereux.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'hiver_noir', 'Hiver noir', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","texte_court":"Le rayon passe à 6 m et un échec divise aussi le Déplacement par deux (sans cumul de ralentissements). Hors combat, dix minutes gèlent l''eau de surface ou des mécanismes ordinaires exposés.","texte_reference":"Étend fortement la zone et l’intensité du froid surnaturel.","lore":"Le Sang glacial étend son absence de chaleur jusqu’à transformer une zone entière. Givre, souffle blanc et surfaces durcies installent un hiver local qui ne dépend ni de la saison ni du climat extérieur.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_ardent', 'Sang Ardent — Larisha', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"consumer","sang":"sang_ardent","portes":{"A":"La brûlure","B":"Le feu"},"description":"Sang de Larisha consacré à la chaleur, la brûlure et l’embrasement. Il peut marquer une cible au contact, enflammer la matière réellement combustible et finir par saturer l’environnement de chaleur surnaturelle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'toucher_ardent', 'Toucher ardent', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","texte_court":"Une attaque de contact payée normalement inflige DGT 5 thermiques, soumis aux protections adaptées ; une matière réellement combustible peut s''enflammer.","texte_reference":"Le contact provoque douleur et brûlure surnaturelles.","lore":"Sous les doigts du Vampire, la chaleur cesse d’être une sensation et devient une agression. Le Sang ardent concentre la brûlure au point de contact, laissant douleur et trace avant même qu’une flamme visible soit nécessaire.","statut_regle":"origine","changements":"DGT 5 rétabli (lot 16)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'marque_incandescente', 'Marque incandescente', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":"1/round, après une blessure réelle du Toucher ardent, la cible est marquée : 2 PV thermiques au début de ses deux prochaines activations. Protections thermiques appliquées ; pas de cumul de marques.","texte_reference":"La brûlure persiste après le contact et peut devenir une Altération appropriée.","lore":"La brûlure de Larisha refuse de s’éteindre avec le geste qui l’a créée. Une chaleur rouge demeure dans la chair ou la matière atteinte, rappel persistant du contact vampirique longtemps après que la main s’est retirée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'embrasement', 'Embrasement', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA","texte_court":"1 PA : à 10 m, enflamme jusqu''à un litre de matière combustible visible. N''enflamme pas d''office un être vivant.","texte_reference":"Enflamme à proximité une matière réellement combustible.","lore":"Le Sang de Larisha transmet sa chaleur à ce qui peut réellement brûler. Le Vampire n’invente pas un combustible : il trouve dans la matière la promesse d’une flamme et la pousse soudain jusqu’à l’incendie.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'fournaise', 'Fournaise', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 2 PA, maintien","texte_court":"2 PA, maintien 1 PA/round : zone de 3 m de rayon ; chaque créature présente au début de son activation subit 2 PV thermiques, alliés compris, protections adaptées appliquées.","texte_reference":"Transforme l’environnement immédiat en zone de chaleur dangereuse.","lore":"La chaleur ardente cesse de rester au contact du Vampire. Air, surfaces et souffle deviennent hostiles autour de lui, comme si la pièce entière avait été rapprochée d’un foyer trop vaste pour être contenu.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_orageux', 'Sang Orageux — Branimir', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"désorganiser","sang":"sang_orageux","portes":{"A":"La décharge","B":"La brume"},"description":"Sang de Branimir fondé sur l’électricité biologique et la conduction. Il surcharge d’abord les nerfs au contact, puis transforme l’espace proche en milieu conducteur où ses décharges peuvent se propager."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'decharge_orageuse', 'Décharge orageuse', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","texte_court":"Une attaque de contact payée normalement inflige DGT 3 électriques ; une blessure réelle impose −3 au prochain test de coordination ou de concentration de la cible avant la fin de son prochain round (1/round).","texte_reference":"Contact électrique violent ; Constitution permet de résister à l’engourdissement ou à l’étourdissement.","lore":"Le contact libère une violence électrique capable de brouiller nerfs et muscles. Le Sang orageux ne se contente pas de brûler : il impose au corps adverse un signal brutal qui concurrence un instant ses propres commandes.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'surcharge_nerveuse', 'Surcharge nerveuse', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","texte_court":"La Décharge inflige DGT 5 ; sur une blessure réelle à DR 3+, la cible perd 1 PA à sa prochaine activation (minimum 1). Aucun arrêt cardiaque automatique.","texte_reference":"Une réussite importante peut provoquer une incapacité sévère et, si la fiction le justifie, une atteinte cardiaque.","lore":"Branimir pousse l’intrusion électrique jusqu’aux fonctions les plus fragiles. Une décharge particulièrement réussie peut faire plus qu’engourdir : rythme cardiaque, coordination et conscience deviennent des systèmes susceptibles d’être momentanément débordés.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'brume_electrostatique', 'Brume électrostatique', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA, maintien","texte_court":"1 PA, maintien 1 PA/round : une brume de 5 m de rayon. Elle porte la Décharge orageuse à distance contre une cible visible dans la zone (Volonté + Force Mentale contre sa Défense physique) ; chaque attaque reste payante.","texte_reference":"Crée autour du Vampire une zone conductrice permettant à ses décharges d’atteindre une cible à courte distance.","lore":"Autour du Vampire, l’air se charge et picote sur la peau. Cette brume conductrice prépare des chemins invisibles à ses décharges, rapprochant électriquement des cibles que quelques mètres séparent encore physiquement.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'arc_orageux', 'Arc orageux', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","texte_court":"2 PA : jusqu''à trois cibles dans la brume, à 3 m au plus l''une de l''autre. Le même jet est comparé à chaque Défense physique ; DGT 3 électriques à chacune, sans la perte de PA de Surcharge nerveuse.","texte_reference":"Une décharge peut traverser plusieurs cibles présentes dans la zone conductrice.","lore":"Branimir laisse la décharge chercher d’autres chemins après le premier impact. Dans un milieu rendu conducteur, l’électricité bondit vers les corps proches comme si chacun devenait momentanément un morceau du même circuit vivant.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_revelateur', 'Sang Révélateur — Zhi Xia', NULL, '{"nature":"vampire","forme":"deux_portes","verrou":"ordre_paliers","identite":"lire les esprits","sang":"sang_revelateur","portes":{"A":"Les pensées","B":"La vérité"},"description":"Sang de Zhi Xia consacré à la pensée, au dévoilement et à la destruction des mensonges surnaturels. Il lit d’abord l’esprit et les impressions présentes, puis confronte illusions, transformations ou pouvoirs actifs à une Vérité plus difficile à falsifier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'lecture_superficielle', 'Lecture superficielle', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR — 1 PA","texte_court":null,"texte_reference":"Opposition mentale. Lit pensées immédiates, impressions et émotions présentes.","lore":"Zhi Xia ouvre une fenêtre étroite sur le présent mental. Pensées immédiates et émotion dominante deviennent perceptibles, assez pour comprendre ce qui occupe quelqu’un maintenant mais pas pour fouiller automatiquement son histoire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'lecture_profonde', 'Lecture profonde', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R — 2 PA","texte_court":null,"texte_reference":"Le DR permet d’aller vers souvenirs, motivations ou indices sur la Nature véritable. Les pensées restent un mélange d’images, de mots et de sensations que le Vampire doit interpréter.","lore":"L’esprit observé cesse d’être seulement une surface d’émotions. Souvenirs, motivations et indices enfouis remontent sous forme d’images, de sensations et de mots partiels que le Vampire doit encore interpréter plutôt que recevoir comme un dossier parfaitement classé.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sang_de_verite', 'Sang de Vérité', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Toucher ou asperger de son sang permet de confronter une illusion ou transformation surnaturelle à un test opposé.","lore":"Le sang du Vampire devient un révélateur hostile aux faux-semblants surnaturels. Au contact d’une illusion ou d’une transformation, il force l’apparence à confronter sa cohérence à quelque chose qui se souvient obstinément du réel.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'dissipation_revelatrice', 'Dissipation révélatrice', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","texte_court":null,"texte_reference":"Peut également supprimer temporairement un pouvoir surnaturel actif sur une cible. Ne permet jamais de forcer une autre personne à se Révéler à travers le Voile.","lore":"Zhi Xia pousse la Vérité au-delà de l’apparence et attaque la manifestation active elle-même. Le Vampire peut faire taire temporairement un pouvoir présent sur quelqu’un sans pour autant déchirer le Voile ni révéler de force ce que le monde protège.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'vampire_sang_condamne', 'Sang Condamné — Ashelia', NULL, '{"nature":"vampire","forme":"une_porte","verrou":"ordre_paliers","identite":"dévorer la magie","sang":"sang_condamne","description":"Sang d’Ashelia lié à la dévoration magique et au remplacement du corps. Sa faim peut absorber vitalité ou manifestations surnaturelles et conduit, à son extrême, à l’abandon d’une enveloppe condamnée pour une autre — au prix de conséquences monstrueuses."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'faim_condamnee', 'Faim condamnée', NULL, '{"nature":"vampire","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R — 1 PA","texte_court":"1 PA, 10 m, Volonté + Force Mentale contre Défense occulte, drain DGT 3 ; récupère jusqu''à 1 + DR PV.","texte_reference":"Aspire à distance une partie de la vitalité ou de l’énergie d’une cible ; la résistance dépend de la nature exacte de ce qui est dévoré.","lore":"La faim d’Ashelia apprend à atteindre ce qui nourrit sans exiger le contact des crocs. Vitalité ou énergie sont tirées à distance vers le Vampire, comme si son organisme refusait d’attendre que la proie soit déjà entre ses mains.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'faim_magique', 'Faim magique', NULL, '{"nature":"vampire","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — Réaction 1 PA","texte_court":"Réaction 1 PA contre une manifestation offensive ; réduit ses DGT de 3 + DR, annule un effet sans dégâts à DR 3+.","texte_reference":"Tente de dévorer une attaque ou manifestation surnaturelle offensive dirigée contre le Vampire.","lore":"Une manifestation hostile peut devenir nourriture plutôt que blessure. Le Vampire ouvre sa faim sur le pouvoir qui arrive et tente d’en dévorer la substance avant qu’elle ne se referme sur lui.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'changement_de_corps', 'Changement de corps', NULL, '{"nature":"vampire","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R — 1/scénario","texte_court":"1/scénario, après une heure, se transférer dans un hôte humain.","texte_reference":"Pouvoir exceptionnel, généralement préparé. Le Vampire abandonne son enveloppe condamnée pour en prendre une nouvelle ; l’ancien corps donne naissance à un Strygoï.","lore":"Ashelia pousse la malédiction jusqu’à traiter le corps comme une enveloppe remplaçable. Le Vampire abandonne une chair condamnée pour s’ancrer ailleurs, laissant derrière lui quelque chose qui ne meurt pas proprement et peut engendrer un monstre autonome.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sens_de_la_magie', 'Sens de la magie', NULL, '{"nature":"vampire","cout":1,"palier":"I","porte":null,"entree_alternative":true,"acces":"SR","texte_court":"Tu sens une magie active à 10 m : sa présence et sa direction, pas sa nature.","texte_reference":"Entrée Semi-Révélée optionnelle du Sang Condamné : perçoit à 10 m la présence et la direction d''une magie active, sans en connaître la nature.","statut_regle":"correction","changements":"Nouveau talent : entrée Semi-Révélée optionnelle (clôture du 29/10, Q4 ; nom validé, décision 22)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
